-- Уникальность событий и версий; ссылки hub/link/event; аудит спутника соответствует ledger.
SELECT count(*) AS n FROM (SELECT event_id AS k FROM {{target:oil_dds__sat_well}} GROUP BY event_id HAVING event_id IS NULL OR count(*)>1 UNION ALL SELECT well_hk AS k FROM {{target:oil_dds__sat_well}} GROUP BY well_hk,entity_version HAVING well_hk IS NULL OR entity_version IS NULL OR count(*)>1 UNION ALL SELECT s.event_id AS k FROM {{target:oil_dds__sat_well}} s LEFT JOIN {{target:oil_dds__hub_well}} h ON h.well_hk=s.well_hk LEFT JOIN {{target:oil_dds__link_well_field}} l ON l.link_hk=s.link_hk LEFT JOIN {{target:oil_dds__event}} e ON e.event_id=s.event_id WHERE h.well_hk IS NULL OR l.link_hk IS NULL OR l.well_hk IS DISTINCT FROM s.well_hk OR e.event_id IS NULL OR s.load_dts IS DISTINCT FROM e.load_dts OR s.record_source IS DISTINCT FROM e.record_source OR s.valid_from IS NULL OR nullif(s.well_name,'') IS NULL OR s.status IS NULL OR s.status NOT IN ('ACTIVE','INACTIVE')) q;
